import { Injectable } from '@angular/core';
import { HashLocationStrategy } from '@angular/common';

/**
 * GWT-style hash location strategy: history tokens look like `#manufacturer`
 * (no leading slash), exactly like the GWTP places of the original app.
 */
@Injectable()
export class GwtHashLocationStrategy extends HashLocationStrategy {
  override path(includeHash = false): string {
    const token = super.path(includeHash); // e.g. "manufacturer" or ""
    return token.length > 0 ? '/' + token.replace(/^\/+/, '') : '';
  }

  override prepareExternalUrl(internal: string): string {
    const token = internal.replace(/^\/+/, '');
    return token.length > 0 ? '#' + token : '#';
  }
}
```

