// src/app/core/messages.service.ts
import { Injectable, signal } from '@angular/core';

export type MessageStyle = 'SUCCESS' | 'ERROR';

export interface AppMessage {
  closeId: number;
  text: string;
  style: MessageStyle;
}

const DEFAULT_CLOSE_DELAY_MS = 5000;

@Injectable({ providedIn: 'root' })
export class MessagesService {
  private nextId = 0;
  private readonly messageList = signal<AppMessage[]>([]);
  readonly messages = this.messageList.asReadonly();

  success(text: string): void {
    this.add(text, 'SUCCESS');
  }

  error(text: string): void {
    this.add(text, 'ERROR');
  }

  close(message: AppMessage): void {
    this.messageList.update((messages) => messages.filter((m) => m.closeId !== message.closeId));
  }

  private add(text: string, style: MessageStyle): void {
    const message: AppMessage = { closeId: ++this.nextId, text, style };
    this.messageList.update((messages) => [...messages, message]);
    setTimeout(() => this.close(message), DEFAULT_CLOSE_DELAY_MS);
  }
}
