import { Injectable } from '@angular/core';
import { HashLocationStrategy } from '@angular/common';

/**
 * A hash location strategy that produces GWT-style history tokens: the
 * original GWTP application used URLs like `...#manufacturer` (no leading
 * slash). This keeps the migrated app's URLs identical to the GWT ones.
 */
@Injectable()
export class GwtHashLocationStrategy extends HashLocationStrategy {
  override path(includeHash = false): string {
    const token = super.path(includeHash);
    const trimmed = token.replace(/^\/+/, '');
    return trimmed.length > 0 ? '/' + trimmed : '';
  }

  override prepareExternalUrl(internal: string): string {
    const token = internal.replace(/^\/+/, '').split('?')[0];
    return '#' + token;
  }
}
