import { Component, inject } from '@angular/core';
import { Router, RouterLink, RouterLinkActive } from '@angular/router';
import { ApiService } from '../core/api.service';
import { MessagesService } from '../core/messages.service';

/**
 * Header widget migrated from `widget/header/`: the menubar used to move
 * between screens plus the user options with the logout button. Login is
 * out of scope (the REST API is not protected), so the user options are
 * always shown, like the GWT application does once logged in.
 */
@Component({
    selector: 'app-header',
    standalone: true,
    imports: [RouterLink, RouterLinkActive],
    template: `
        <div class="header">
            <div class="header-content">
                <div class="float-left application-title">CarStore</div>

                <div id="gwt-debug-menubar" class="float-left menu-bar-wrapper">
                    <a routerLink="/manufacturer" routerLinkActive="menu-active">Manufacturers</a>
                    <a routerLink="/cars" routerLinkActive="menu-active">Cars</a>
                    <a routerLink="/rating" routerLinkActive="menu-active">Ratings</a>
                    <a routerLink="/report" routerLinkActive="menu-active">Reports</a>
                    <a routerLink="/stats" routerLinkActive="menu-active">Statistics</a>
                </div>

                <div class="float-right padding-top">
                    <div class="user-info">Hello!</div>
                    <div class="float-left">
                        <button
                            id="gwt-debug-logout"
                            class="logout-button"
                            (click)="logout()">
                            Logout
                        </button>
                    </div>
                    <div class="clear"></div>
                </div>

                <div class="clear"></div>
            </div>
        </div>
    `,
    styles: `
        .header {
            border-bottom: 1px solid #45a0ec;
        }

        .header-content {
            width: 1000px;
            margin: 0 auto;
            padding: 5px 0;
        }

        .float-left {
            float: left;
        }

        .float-right {
            float: right;
        }

        .padding-top {
            margin-top: 10px;
        }

        .clear {
            clear: both;
        }

        .application-title {
            padding: 15px 0 0 10px;
            font-size: 16px;
            font-weight: bold;
        }

        .menu-bar-wrapper {
            margin-left: 30px;
            padding-top: 10px;
        }

        .menu-bar-wrapper a {
            color: #45a0ec;
            text-decoration: none;
            margin-right: 15px;
            padding: 5px 10px;
        }

        .menu-bar-wrapper a:hover {
            text-decoration: underline;
        }

        .menu-bar-wrapper a.menu-active {
            background: #45a0ec;
            border-radius: 4px;
            color: #fff;
        }

        .user-info {
            float: left;
            padding: 6px 20px 0 0;
            margin-right: 11px;
            border-right: 1px solid #aeaeae;
        }

        .logout-button {
            background: none;
            border: none;
            color: #45a0ec;
            font-size: 14px;
            cursor: pointer;
        }

        .logout-button:hover {
            text-decoration: underline;
            color: #1d6098;
        }
    `,
})
export class HeaderComponent {
    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);
    private readonly router = inject(Router);

    async logout(): Promise<void> {
        try {
            await this.api.logout();
        } catch {
            this.messages.error('Error while trying to log you out.');
        } finally {
            await this.router.navigateByUrl('/manufacturer');
        }
    }
}

