import { Component, inject, OnInit } from '@angular/core';
import { ApiService } from '../core/api.service';
import { MessagesService } from '../core/messages.service';
import { ManufacturerDto } from '../core/models';
import { EditManufacturerDialogComponent } from './edit-manufacturer-dialog.component';

/**
 * Manufacturers screen migrated from `application/manufacturer/`:
 * the manufacturer CellTable (ID, Name, Edit, Delete columns) with the
 * create/edit popup.
 *
 * Like the GWT view, deletes are confirmed with `window.confirm`, edits
 * replace the row in place and creations are appended at the end of the
 * table without reloading the whole list.
 */
@Component({
    selector: 'app-manufacturers',
    standalone: true,
    imports: [EditManufacturerDialogComponent],
    templateUrl: './manufacturers.component.html',
})
export class ManufacturersComponent implements OnInit {
    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);

    manufacturers: ManufacturerDto[] = [];
    editorOpen = false;
    editing: ManufacturerDto | null = null;

    ngOnInit(): void {
        void this.loadManufacturers();
    }

    onCreate(): void {
        this.editing = null;
        this.editorOpen = true;
    }

    onEdit(manufacturer: ManufacturerDto): void {
        this.editing = manufacturer;
        this.editorOpen = true;
    }

    onEditorClose(): void {
        this.editorOpen = false;
    }

    async onEditorSave(name: string): Promise<void> {
        const edited = this.editing;
        const manufacturer: ManufacturerDto =
            edited === null ? { id: null, name, cars: [] } : { ...edited, name };

        try {
            const saved = await this.api.saveManufacturer(manufacturer);
            if (edited === null) {
                this.manufacturers = [...this.manufacturers, saved];
            } else {
                this.manufacturers = this.manufacturers.map((m) => (m === edited ? saved : m));
            }
            this.messages.success('The manufacturer has been saved.');
            this.editorOpen = false;
        } catch {
            this.messages.error('The manufacturer could not be saved.');
        }
    }

    async onDeleteManufacturer(manufacturer: ManufacturerDto): Promise<void> {
        const confirmed = window.confirm(
            `Are you sure you want to delete ${manufacturer.name}?`,
        );
        if (!confirmed) {
            return;
        }

        try {
            await this.api.deleteManufacturer(manufacturer.id ?? '');
            this.manufacturers = this.manufacturers.filter((m) => m !== manufacturer);
        } catch {
            this.messages.error('The manufacturer could not be deleted.');
        }
    }

    private async loadManufacturers(): Promise<void> {
        try {
            this.manufacturers = await this.api.getManufacturers();
        } catch {
            this.messages.error('The manufacturers could not be loaded.');
        }
    }
}

