import { FormsModule } from '@angular/forms';
import { ManufacturerDto } from '../core/models';

/**
 * Create / edit manufacturer popup, migrated from
 * `manufacturer/ui/EditManufacturer*`. It is a dumb editor like the GWT
 * view: `Save` flushes the name to the presenter, `Close` cancels.
 */
@Component({
    selector: 'app-edit-manufacturer-dialog',
    standalone: true,
    imports: [FormsModule],
    template: `
        <div class="popup-glass" (click)="close()"></div>
        <div class="popup">
            <div id="gwt-debug-manufacturer-editor" class="editor">
                <div class="editor-row">
                    <label for="gwt-debug-manufacturer-input">Name:</label>
                    <input
                        id="gwt-debug-manufacturer-input"
                        type="text"
                        name="name"
                        autocomplete="off"
                        [(ngModel)]="name" />
                </div>

                <div class="editor-row editor-buttons">
                    <button type="button" id="gwt-debug-manufacturer-save" (click)="save()">
                        Save
                    </button>
                    <button type="button" id="gwt-debug-manufacturer-close" (click)="close()">
                        Close
                    </button>
                </div>
            </div>
        </div>
    `,
})
export class EditManufacturerDialogComponent {
    @Input() manufacturer: ManufacturerDto | null = null;
    @Output() saved = new EventEmitter<string>();
    @Output() closed = new EventEmitter<void>();

    name = '';

    ngOnInit(): void {
        this.name = this.manufacturer?.name ?? '';
    }

    save(): void {
        this.saved.emit(this.name);
    }

    close(): void {
        this.closed.emit();
    }
}

