import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CarDto, carLabel } from '../core/models';

/** Value flushed by the rating editor on save, like `driver.flush()`. */
export interface RatingDraft {
    car: CarDto | null;
    rating: number | null;
}

/**
 * Create rating popup migrated from `rating/ui/EditRating*`: a car list
 * (defaulting to the first car, like the GWT `ValueListBox`), a rating
 * input and the Save / Close buttons.
 */
@Component({
    selector: 'app-edit-rating-dialog',
    standalone: true,
    imports: [FormsModule],
    template: `
        <div class="popup-glass" (click)="close()"></div>
        <div class="popup">
            <div class="editor">
                <div class="editor-row">
                    <label for="rating-car">Car:</label>
                    <select id="rating-car" name="car" [(ngModel)]="car">
                        @for (option of cars; track option) {
                            <option [ngValue]="option">{{ carLabel(option) }}</option>
                        }
                    </select>
                </div>

                <div class="editor-row">
                    <label for="gwt-debug-ratingInput">Your rating:</label>
                    <input
                        id="gwt-debug-ratingInput"
                        type="text"
                        name="rating"
                        maxlength="3"
                        autocomplete="off"
                        [(ngModel)]="ratingText" />
                </div>

                <div class="editor-row editor-buttons">
                    <button type="button" id="gwt-debug-ratingSave" (click)="save()">Save</button>
                    <button type="button" (click)="close()">Close</button>
                </div>
            </div>
        </div>
    `,
})
export class EditRatingDialogComponent {
    @Input() cars: CarDto[] = [];
    @Output() saved = new EventEmitter<RatingDraft>();
    @Output() closed = new EventEmitter<void>();

    car: CarDto | null = null;
    ratingText = '';

    ngOnInit(): void {
        // Like the GWT ValueListBox: the first car is selected by default.
        this.car = this.cars.length > 0 ? this.cars[0] : null;
    }

    carLabel(car: CarDto): string {
        return carLabelOf(car);
    }

    save(): void {
        const text = this.ratingText.trim();
        const rating = text.length === 0 ? null : Number(text);
        this.saved.emit({ car: this.car, rating });
    }

    close(): void {
        this.closed.emit();
    }
}

function carLabelOf(car: CarDto): string {
    return carLabel(car);
}

