import { Component, inject, OnInit } from '@angular/core';
import { ApiService } from '../core/api.service';
import { MessagesService } from '../core/messages.service';
import { CarDto, RatingDto, carLabel } from '../core/models';
import { EditRatingDialogComponent, RatingDraft } from './edit-rating-dialog.component';

/**
 * Ratings screen migrated from `application/rating/`: the rating
 * CellTable (ID, Car, Rating, Delete columns) with the create popup.
 *
 * The Car column renders `manufacturer/model` like `RatingDto.toString()`
 * in the GWT application; deletes are confirmed with `window.confirm`.
 */
@Component({
    selector: 'app-ratings',
    standalone: true,
    imports: [EditRatingDialogComponent],
    templateUrl: './ratings.component.html',
})
export class RatingsComponent implements OnInit {
    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);

    ratings: RatingDto[] = [];
    cars: CarDto[] = [];
    editorOpen = false;

    ngOnInit(): void {
        void this.loadRatings();
    }

    carLabel(car: CarDto | null): string {
        return carLabel(car);
    }

    async onCreate(): Promise<void> {
        // Like the GWT EditRatingPresenter: the cars are loaded before the
        // popup is revealed.
        try {
            this.cars = await this.api.getCars();
            this.editorOpen = true;
        } catch {
            this.messages.error('The cars could not be loaded.');
        }
    }

    onEditorClose(): void {
        this.editorOpen = false;
    }

    async onEditorSave(draft: RatingDraft): Promise<void> {
        try {
            const saved = await this.api.saveRating({
                id: null,
                car: draft.car,
                rating: draft.rating,
            });
            this.ratings = [...this.ratings, saved];
            this.messages.success('The rating has been saved.');
            this.editorOpen = false;
        } catch {
            this.messages.error('The rating could not be saved.');
        }
    }

    async onDeleteRating(rating: RatingDto): Promise<void> {
        // Same message as the GWT RatingView (no space before the car).
        const confirmed = window.confirm(
            `Are you sure you want to delete${carLabel(rating.car)}?`,
        );
        if (!confirmed) {
            return;
        }

        try {
            await this.api.deleteRating(rating.id ?? '');
            this.ratings = this.ratings.filter((candidate) => candidate !== rating);
        } catch {
            this.messages.error('The rating could not be deleted.');
        }
    }

    private async loadRatings(): Promise<void> {
        try {
            this.ratings = await this.api.getRatings();
        } catch {
            this.messages.error('The ratings could not be loaded.');
        }
    }
}

