.big-title h2 {
    float: left;
    margin: 0;
    color: #1d6098;
}

.big-title div {
    float: right;
}

.add-action {
    background: #57a957;
    border: 1px solid #57a957;
    border-radius: 20px;
    color: #fff;
    cursor: pointer;
    font-size: 18px;
    font-weight: bold;
    line-height: 20px;
    height: 28px;
    width: 28px;
    padding: 0;
}

.add-action:hover {
    background: #489348;
    border-color: #489348;
}

.table-wrapper {
    margin-top: 20px;
}

/* CellTable-like tables */
table {
    width: 100%;
    border-collapse: collapse;
}

th,
td {
    border: 1px solid #d5d5d5;
    padding: 6px 10px;
    text-align: left;
}

thead th {
    background: #f0f0f0;
    border-bottom: 2px solid #d5d5d5;
    font-weight: bold;
}

tbody tr:nth-child(even) {
    background: #fafafa;
}

tbody tr:hover {
    background: #eef4fb;
}

.column-id {
    width: 90px;
}

.column-action {
    width: 90px;
    text-align: center;
}

.column-rating {
    width: 90px;
}

td button {
    cursor: pointer;
}

.not-migrated {
    color: #777;
    padding: 20px;
}

/* Popup panels, like the GWT PopupPanel with a glass panel */
.popup-glass {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background: rgba(0, 0, 0, 0.45);
    z-index: 100;
}

.popup {
    position: fixed;
    top: 30%;
    left: 50%;
    transform: translateX(-50%);
    z-index: 101;
}

.editor {
    background: #fff;
    border: 1px solid #999;
    border-radius: 4px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
    padding: 20px;
    min-width: 320px;
}

.editor-row {
    margin: 10px 0;
}

.editor-row label {
    display: inline-block;
    width: 90px;
}

.editor-row input,
.editor-row select {
    padding: 4px;
    width: 180px;
}

.editor-buttons {
    margin-top: 20px;
    text-align: right;
}

.editor-buttons button {
    cursor: pointer;
    margin-left: 10px;
    padding: 4px 14px;
}
